css:
.ed__rule { display: block; width: 3.5rem; height: 3px; border-radius: 3px; background: linear-gradient(90deg, #6b8e36, #eec02b); margin-bottom: clamp(1.4rem, 3vw, 2.2rem); }
.ed__grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2.3fr); gap: var(--os-space-lg); }
.ed__day { margin: 0; font-family: var(--os-font-heading); font-size: 2.4rem; line-height: 1.1; color: var(--os-color-heading); }
.ed__meta { margin: .4rem 0 0; font-size: .9rem; line-height: 1.4; color: var(--os-color-text-muted); }
.ed__next b { color: var(--os-color-link); }
.ed__title { margin: 0 0 1.2rem; font-size: clamp(1.9rem, 1.2rem + 2.4vw, 3rem); line-height: 1.08; }
.ed__deck { margin: 0 0 1.2rem; max-width: 30ch; font-family: var(--os-font-heading); font-size: clamp(1.25rem, 1.05rem + .6vw, 1.55rem); line-height: 1.3; color: var(--os-color-heading); }
.ed__oh { margin: 0 0 .8rem; font-size: 1.35rem; }
.ed__offers { margin: 0 0 1.8rem; padding-left: 1.1rem; list-style: disc; }
.ed__offers li { margin: 0 0 .35rem; display: list-item; list-style: disc; }
.ed__body p { margin: 0 0 1.1rem; }
.ed__cta { margin: 1.4rem 0 0; }
.ed__cta a { text-decoration: none; }
.ed__btn { display: inline-flex; align-items: center; min-height: 44px; padding: .45rem 1rem; border: 2px solid currentColor; border-radius: 999px; font-weight: 700; font-size: .92rem; color: var(--os-color-heading); }
@media (max-width: 767px) { .ed__grid { grid-template-columns: 1fr; gap: .8rem; } .ed__day { font-size: 1.9rem; } }
